from abc import ABCMeta, abstractmethod
import six


@six.add_metaclass(ABCMeta)
class ProcessFactory(object):
    """
    Factory for creating processes.
    """

    @abstractmethod
    def create_process(self, command):
        """
        Create a process, that executes the command.

        :param str command: command to be executed by the process

        :rtype: Process
        :returns: process, which executes the command
        """
